CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TABLE tenants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), slug VARCHAR(120) UNIQUE NOT NULL, name VARCHAR(255) NOT NULL, status VARCHAR(40) NOT NULL, default_locale VARCHAR(10) NOT NULL, currency_code VARCHAR(3) NOT NULL, primary_domain VARCHAR(255), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE tenant_settings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), brand_name VARCHAR(255) NOT NULL, primary_color VARCHAR(20) NOT NULL, secondary_color VARCHAR(20) NOT NULL, default_commission_rate NUMERIC(10,2) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(255) NOT NULL, preferred_locale VARCHAR(10) NOT NULL, preferred_currency VARCHAR(3) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID REFERENCES tenants(id), code VARCHAR(80) NOT NULL, name VARCHAR(120) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE permissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(120) UNIQUE NOT NULL, name VARCHAR(255) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE user_roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID REFERENCES tenants(id), user_id UUID NOT NULL REFERENCES users(id), role_id UUID NOT NULL REFERENCES roles(id), status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE role_permissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), role_id UUID NOT NULL REFERENCES roles(id), permission_id UUID NOT NULL REFERENCES permissions(id), status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE user_profiles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), user_id UUID NOT NULL REFERENCES users(id), document_number VARCHAR(40), phone_number VARCHAR(40), avatar_url VARCHAR(500), status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE user_addresses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), user_id UUID NOT NULL REFERENCES users(id), label VARCHAR(80), recipient_name VARCHAR(255) NOT NULL, postal_code VARCHAR(20) NOT NULL, street VARCHAR(255) NOT NULL, number VARCHAR(40) NOT NULL, district VARCHAR(120) NOT NULL, city VARCHAR(120) NOT NULL, state VARCHAR(120) NOT NULL, country_code VARCHAR(2) NOT NULL, is_default BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE sellers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), user_id UUID NOT NULL REFERENCES users(id), legal_name VARCHAR(255) NOT NULL, document_number VARCHAR(40) NOT NULL, approval_status VARCHAR(40) NOT NULL DEFAULT 'PENDING', premium_badge BOOLEAN NOT NULL DEFAULT FALSE, reputation_score NUMERIC(5,2) NOT NULL DEFAULT 0, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE seller_documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), seller_id UUID NOT NULL REFERENCES sellers(id), document_type VARCHAR(80) NOT NULL, file_url VARCHAR(600) NOT NULL, review_status VARCHAR(40) NOT NULL DEFAULT 'PENDING', status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE stores (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), seller_id UUID NOT NULL REFERENCES sellers(id), name VARCHAR(255) NOT NULL, slug VARCHAR(180) NOT NULL, description TEXT, logo_url VARCHAR(600), banner_url VARCHAR(600), reputation_score NUMERIC(5,2) NOT NULL DEFAULT 0, premium_badge BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), parent_id UUID REFERENCES categories(id), name VARCHAR(255) NOT NULL, slug VARCHAR(180) NOT NULL, sort_order INT NOT NULL DEFAULT 0, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE brands (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(255) NOT NULL, slug VARCHAR(180) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE product_attributes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), category_id UUID REFERENCES categories(id), code VARCHAR(80) NOT NULL, name VARCHAR(255) NOT NULL, input_type VARCHAR(40) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE product_attribute_values (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), attribute_id UUID NOT NULL REFERENCES product_attributes(id), product_id UUID, product_variant_id UUID, value_text TEXT NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), store_id UUID NOT NULL REFERENCES stores(id), category_id UUID NOT NULL REFERENCES categories(id), brand_id UUID REFERENCES brands(id), sku VARCHAR(120) NOT NULL, name VARCHAR(255) NOT NULL, seo_slug VARCHAR(220), description TEXT NOT NULL, price NUMERIC(14,2) NOT NULL, promotional_price NUMERIC(14,2), currency_code VARCHAR(3) NOT NULL, approval_status VARCHAR(40) NOT NULL DEFAULT 'PENDING', status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE product_images (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), product_id UUID NOT NULL REFERENCES products(id), url VARCHAR(600) NOT NULL, alt_text VARCHAR(255), sort_order INT NOT NULL DEFAULT 0, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE product_videos (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), product_id UUID NOT NULL REFERENCES products(id), url VARCHAR(600) NOT NULL, provider VARCHAR(40) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE product_variants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), product_id UUID NOT NULL REFERENCES products(id), sku VARCHAR(120) NOT NULL, name VARCHAR(255) NOT NULL, price NUMERIC(14,2) NOT NULL, promotional_price NUMERIC(14,2), status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE stock_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), product_id UUID REFERENCES products(id), product_variant_id UUID REFERENCES product_variants(id), available_quantity INT NOT NULL DEFAULT 0, reserved_quantity INT NOT NULL DEFAULT 0, warehouse_code VARCHAR(80), status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE carts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), user_id UUID REFERENCES users(id), session_id VARCHAR(120), currency_code VARCHAR(3) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE cart_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), cart_id UUID NOT NULL REFERENCES carts(id), product_id UUID NOT NULL REFERENCES products(id), product_variant_id UUID REFERENCES product_variants(id), seller_id UUID NOT NULL REFERENCES sellers(id), quantity INT NOT NULL, unit_price NUMERIC(14,2) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE order_groups (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), buyer_id UUID NOT NULL REFERENCES users(id), cart_id UUID REFERENCES carts(id), status VARCHAR(40) NOT NULL DEFAULT 'PENDING', currency_code VARCHAR(3) NOT NULL, total_amount NUMERIC(14,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), order_group_id UUID NOT NULL REFERENCES order_groups(id), seller_id UUID NOT NULL REFERENCES sellers(id), buyer_id UUID NOT NULL REFERENCES users(id), store_id UUID NOT NULL REFERENCES stores(id), currency_code VARCHAR(3) NOT NULL, subtotal_amount NUMERIC(14,2) NOT NULL, shipping_amount NUMERIC(14,2) NOT NULL, total_amount NUMERIC(14,2) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'PENDING_PAYMENT', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), order_id UUID NOT NULL REFERENCES orders(id), product_id UUID NOT NULL REFERENCES products(id), product_variant_id UUID REFERENCES product_variants(id), seller_id UUID NOT NULL REFERENCES sellers(id), quantity INT NOT NULL, unit_price NUMERIC(14,2) NOT NULL, commission_amount NUMERIC(14,2) NOT NULL DEFAULT 0, total_amount NUMERIC(14,2) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE order_status_history (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), order_id UUID NOT NULL REFERENCES orders(id), previous_status VARCHAR(40), new_status VARCHAR(40) NOT NULL, note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE shipments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), order_id UUID NOT NULL REFERENCES orders(id), carrier_name VARCHAR(120), service_level VARCHAR(80), tracking_code VARCHAR(120), shipping_cost NUMERIC(14,2) NOT NULL DEFAULT 0, estimated_delivery_at TIMESTAMPTZ, dispatched_at TIMESTAMPTZ, delivered_at TIMESTAMPTZ, status VARCHAR(40) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE shipment_tracking (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), shipment_id UUID NOT NULL REFERENCES shipments(id), tracking_status VARCHAR(80) NOT NULL, description TEXT, event_at TIMESTAMPTZ NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), order_group_id UUID NOT NULL REFERENCES order_groups(id), provider VARCHAR(80) NOT NULL, method VARCHAR(40) NOT NULL, amount NUMERIC(14,2) NOT NULL, currency_code VARCHAR(3) NOT NULL, idempotency_key VARCHAR(120) UNIQUE NOT NULL, external_reference VARCHAR(180), status VARCHAR(40) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE payment_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), payment_id UUID NOT NULL REFERENCES payments(id), provider_transaction_id VARCHAR(180), transaction_type VARCHAR(40) NOT NULL, amount NUMERIC(14,2) NOT NULL, raw_payload JSONB, status VARCHAR(40) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE payment_webhooks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), provider VARCHAR(80) NOT NULL, event_type VARCHAR(80) NOT NULL, payload JSONB NOT NULL, processed BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(40) NOT NULL DEFAULT 'RECEIVED', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE pix_charges (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), payment_id UUID NOT NULL REFERENCES payments(id), provider_charge_id VARCHAR(180) NOT NULL, qr_code TEXT NOT NULL, copy_paste_code TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, paid_at TIMESTAMPTZ, status VARCHAR(40) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE refunds (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), payment_id UUID NOT NULL REFERENCES payments(id), order_id UUID REFERENCES orders(id), amount NUMERIC(14,2) NOT NULL, reason TEXT, status VARCHAR(40) NOT NULL DEFAULT 'REQUESTED', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE seller_payouts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), seller_id UUID NOT NULL REFERENCES sellers(id), order_id UUID REFERENCES orders(id), gross_amount NUMERIC(14,2) NOT NULL, commission_amount NUMERIC(14,2) NOT NULL, net_amount NUMERIC(14,2) NOT NULL, available_at TIMESTAMPTZ, paid_at TIMESTAMPTZ, status VARCHAR(40) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE commissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), order_item_id UUID REFERENCES order_items(id), seller_id UUID NOT NULL REFERENCES sellers(id), rate NUMERIC(10,2) NOT NULL, amount NUMERIC(14,2) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE coupons (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), seller_id UUID REFERENCES sellers(id), code VARCHAR(60) NOT NULL, description VARCHAR(255), discount_type VARCHAR(20) NOT NULL, discount_value NUMERIC(14,2) NOT NULL, starts_at TIMESTAMPTZ, ends_at TIMESTAMPTZ, max_uses INT, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE coupon_rules (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), coupon_id UUID NOT NULL REFERENCES coupons(id), rule_type VARCHAR(40) NOT NULL, rule_value VARCHAR(255) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE coupon_usages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), coupon_id UUID NOT NULL REFERENCES coupons(id), user_id UUID NOT NULL REFERENCES users(id), order_id UUID REFERENCES orders(id), status VARCHAR(40) NOT NULL DEFAULT 'USED', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE reviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), product_id UUID NOT NULL REFERENCES products(id), user_id UUID NOT NULL REFERENCES users(id), rating INT NOT NULL, title VARCHAR(255), comment TEXT, approved BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(40) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE seller_ratings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), seller_id UUID NOT NULL REFERENCES sellers(id), user_id UUID NOT NULL REFERENCES users(id), rating INT NOT NULL, comment TEXT, response_time_score NUMERIC(5,2), shipping_time_score NUMERIC(5,2), status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE chats (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), buyer_id UUID NOT NULL REFERENCES users(id), seller_id UUID NOT NULL REFERENCES sellers(id), order_id UUID REFERENCES orders(id), status VARCHAR(40) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE chat_messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), chat_id UUID NOT NULL REFERENCES chats(id), sender_user_id UUID REFERENCES users(id), message_type VARCHAR(20) NOT NULL, content TEXT NOT NULL, attachment_url VARCHAR(600), moderation_status VARCHAR(40) NOT NULL DEFAULT 'APPROVED', status VARCHAR(40) NOT NULL DEFAULT 'SENT', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), user_id UUID NOT NULL REFERENCES users(id), channel VARCHAR(20) NOT NULL, title VARCHAR(255) NOT NULL, body TEXT NOT NULL, read_at TIMESTAMPTZ, status VARCHAR(40) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE support_tickets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), user_id UUID NOT NULL REFERENCES users(id), order_id UUID REFERENCES orders(id), subject VARCHAR(255) NOT NULL, priority VARCHAR(20) NOT NULL DEFAULT 'MEDIUM', status VARCHAR(40) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE support_messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), ticket_id UUID NOT NULL REFERENCES support_tickets(id), sender_user_id UUID REFERENCES users(id), message TEXT NOT NULL, attachment_url VARCHAR(600), status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE disputes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), order_id UUID NOT NULL REFERENCES orders(id), opened_by UUID NOT NULL REFERENCES users(id), reason TEXT NOT NULL, resolution TEXT, status VARCHAR(40) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE banners (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), locale VARCHAR(10) NOT NULL, title VARCHAR(255) NOT NULL, image_url VARCHAR(600) NOT NULL, target_url VARCHAR(600), sort_order INT NOT NULL DEFAULT 0, starts_at TIMESTAMPTZ, ends_at TIMESTAMPTZ, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE cms_pages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), locale VARCHAR(10) NOT NULL, slug VARCHAR(180) NOT NULL, title VARCHAR(255) NOT NULL, content TEXT NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID REFERENCES tenants(id), actor_user_id UUID, action VARCHAR(120) NOT NULL, resource_type VARCHAR(120) NOT NULL, resource_id VARCHAR(120), metadata JSONB, status VARCHAR(40) NOT NULL DEFAULT 'RECORDED', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE security_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID REFERENCES tenants(id), user_id UUID, ip_address VARCHAR(120), event_type VARCHAR(120) NOT NULL, severity VARCHAR(20) NOT NULL, details JSONB, status VARCHAR(40) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE fraud_analysis (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), order_id UUID REFERENCES orders(id), payment_id UUID REFERENCES payments(id), risk_score NUMERIC(5,2) NOT NULL DEFAULT 0, decision VARCHAR(40) NOT NULL DEFAULT 'REVIEW', reason_codes JSONB, reviewed_by UUID, status VARCHAR(40) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE integrations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), integration_type VARCHAR(80) NOT NULL, provider VARCHAR(120) NOT NULL, config JSONB NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE webhooks_outbox (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID REFERENCES tenants(id), target_url VARCHAR(600) NOT NULL, event_type VARCHAR(120) NOT NULL, payload JSONB NOT NULL, delivery_attempts INT NOT NULL DEFAULT 0, next_retry_at TIMESTAMPTZ, status VARCHAR(40) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
CREATE TABLE outbox_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), aggregate_type VARCHAR(120) NOT NULL, aggregate_id VARCHAR(120) NOT NULL, event_type VARCHAR(120) NOT NULL, payload JSONB NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'PENDING', published_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_by UUID, updated_by UUID, deleted_at TIMESTAMPTZ);
